import os
import requests

BASE_URL = os.getenv('MERCADO_LIBRE_BASE_URL', 'https://api.mercadolibre.example')
TIMEOUT_SECONDS = 10

def consultar_publicaciones():
    try:
        response = requests.get(f'{BASE_URL}/items', timeout=TIMEOUT_SECONDS)
        response.raise_for_status()
        return response.json()
    except requests.RequestException as error:
        return {'error': str(error)}
